-- =====================================================================
-- 0048 — Calendário de conteúdo (importado do Notion "Calendários") e
-- ideias do Brainstorming (viram Sugestões do tipo ideia).
-- Leitura: todos os usuários autenticados. Escrita: liderança.
-- Pode rodar mais de uma vez (usa notion_id / título). Rode DEPOIS da 0047.
-- =====================================================================

create table if not exists calendario_conteudo (
  id uuid primary key default gen_random_uuid(),
  notion_id text unique,
  nome text not null,
  data date,
  status text not null default 'Não iniciada',
  tipo text,                       -- Redes Sociais | E-mail Marketing | Oferta | Visita | Podcast
  canais jsonb not null default '[]'::jsonb,
  responsaveis jsonb not null default '[]'::jsonb,
  tipo_post text,                  -- Stories | Feed | Reels | Carrossel | Vídeo
  objetivo text,
  publico jsonb not null default '[]'::jsonb,
  tags text,
  created_at timestamptz not null default now()
);
create index if not exists calendario_conteudo_data_idx on calendario_conteudo (data);

alter table calendario_conteudo enable row level security;
drop policy if exists "calendario_select" on calendario_conteudo;
create policy "calendario_select" on calendario_conteudo
  for select using (auth.uid() is not null);
drop policy if exists "calendario_insert" on calendario_conteudo;
create policy "calendario_insert" on calendario_conteudo
  for insert with check (public.eh_lideranca());
drop policy if exists "calendario_update" on calendario_conteudo;
create policy "calendario_update" on calendario_conteudo
  for update using (public.eh_lideranca());
drop policy if exists "calendario_delete" on calendario_conteudo;
create policy "calendario_delete" on calendario_conteudo
  for delete using (public.eh_lideranca());

insert into calendario_conteudo
  (notion_id, nome, data, status, tipo, canais, responsaveis, tipo_post, objetivo, publico, tags)
select t.notion_id, t.nome, t.data::date, t.status, t.tipo, t.canais, t.responsaveis,
       t.tipo_post, t.objetivo, t.publico, t.tags
