-- Brainstorming (Notion): 2 ideias viram sugestões do tipo ideia.
insert into sugestoes (tipo, titulo, descricao, autor_id)
select 'ideia', i.titulo, i.descricao,
       (select p.id from profiles p where lower(p.email) = 'thiago.leal@litoralverde.com.br' limit 1)
from (values
  ('Assinatura Instagram para conteúdo exclusivo',
   'Importada do Notion (Sessão de Brainstorming). Categoria: Topo do funil · Prioridade: Baixa.'),
  ('Linkedin - B2B',
   'Importada do Notion (Sessão de Brainstorming). Categoria: Topo do funil · Prioridade: Baixa.')
) as i(titulo, descricao)
where exists (select 1 from profiles p where lower(p.email) = 'thiago.leal@litoralverde.com.br')
  and not exists (select 1 from sugestoes s where s.titulo = i.titulo);
